/* @lc app=leetcode id=3343 lang=kotlin */ class Solution { fun fa(i: Int): Long = (1..i).fold(1L) { a, b -> a * b % 1_000_000_007L } fun iv(x: Long): Long = java.math.BigInteger.valueOf(x).modInverse(java.math.BigInteger.valueOf(1_000_000_007L)).toLong() fun countBalancedPermutations(num: String): Int = 1_000_000_007L.let { M -> num.sumOf { it - '0' }.let { tot -> if (tot % 2 == 1) 0 else (tot / 2).let { T -> ((num.length + 1) / 2).let { e -> (0..80).map { iv(fa(it)) }.let { ivf -> (0..9).map { d -> num.count { it == '0' + d } }.let { c -> (0..9).fold(Array(e + 1) { j -> LongArray(T + 1) { s -> if (j == 0 && s == 0) 1L else 0L } }) { f, d -> Array(e + 1) { LongArray(T + 1) }.also { nf -> (0..e).forEach { j -> (0..T).forEach { s -> if (f[j][s] != 0L) (0..minOf(c[d], e - j)).filter { a -> s + d * a <= T }.forEach { a -> nf[j + a][s + d * a] = (nf[j + a][s + d * a] + f[j][s] * ivf[a] % M * ivf[c[d] - a]) % M } } } } }[e][T].let { (it * fa(e) % M * fa(num.length - e) % M).toInt() } } } } } } } }